arguments.command:
python3 - <<'PY'
from fastapi.sse import ServerSentEvent

def test_sse_validation():
    print("--- Testing ID validation ---")
    # 1. Valid ID
    try:
        ServerSentEvent(id="test-id")
        print("PASS: Valid ID")
    except Exception as e:
        print(f"FAIL: Valid ID raised exception: {e}")

    # 2. Invalid ID (newline)
    try:
        ServerSentEvent(id="test-id\n")
        print("FAIL: Invalid ID (newline) did not raise exception")
    except ValueError as e:
        print(f"PASS: Invalid ID (newline) raised expected error: {e}")
    except Exception as e:
        print(f"FAIL: Invalid ID (newline) raised wrong exception: {e}")

    # 3. Invalid ID (carriage return)
    try:
        ServerSentEvent(id="test-id\r")
        print("FAIL: Invalid ID (CR) did not raise exception")
    except ValueError as e:
        print(f"PASS: Invalid ID (CR) raised expected error: {e}")
    except Exception as e:
        print(f"FAIL: Invalid ID (CR) raised wrong exception: {e}")

    # 4. Invalid ID (null character)
    try:
        ServerSentEvent(id="test-id\0")
        print("FAIL: Invalid ID (null) did not raise exception")
    except ValueError as e:
        print(f"PASS: Invalid ID (null) raised expected error: {e}")
    except Exception as e:
        print(f"FAIL: Invalid ID (null) raised wrong exception: {e}")

    print("\n--- Testing Event validation ---")
    # 5. Valid Event
    try:
        ServerSentEvent(event="test-event")
        print("PASS: Valid Event")
    except Exception as e:
        print(f"FAIL: Valid Event raised exception: {e}")

    # 6. Invalid Event (newline)
    try:
        ServerSentEvent(event="test-event\n")
        print("FAIL: Invalid Event (newline) did not raise exception")
    except ValueError as e:
        print(f"PASS: Invalid Event (newline) raised expected error: {e}")
    except Exception as e:
        print(f"FAIL: Invalid Event (newline) raised wrong exception: {e}")

test_sse_validation()
